# arithmetic
SELECT 1 + 2, 7 / 2, 7 DIV 2, 7 % 3, -7 % 3, 2 * 3.5, 0.1 + 0.2, 10 / 4, 10 / 5
SELECT 1 / 0, 5 % 0, 5 DIV 0, MOD(5, 0)
SELECT -(3), +3, 2 - 3, - 3 + 5, 2 * -3, 2 - -3
SELECT '3' + 4, '3abc' + 4, 'abc' + 1, '1.5' + 1, ' 3' + 1, '0x10' + 0, '1e2' + 0
SELECT NULL + 1, 1 + NULL, NULL * 0, NULL / 1, -NULL
SELECT 9223372036854775807 + 1, 9223372036854775807 * 2, -9223372036854775808 - 1
SELECT 5 / 3, 5.0 / 3, 1 / 3, 2 / 3, 1 / 7, 100 / 3
SELECT 3 * 1.1, 0.1 * 3, 1.0 * 3, 2.50 + 1, 1e2 * 2
SELECT 5 - 5.0, 5 * 1.0, 10 / 2.0
# rounding and number functions
SELECT ROUND(2.5), ROUND(-2.5), ROUND(2.4), ROUND(3.5), ROUND(1.255, 2), ROUND(1234, -2), ROUND(1.5), ROUND(0.5), ROUND(-0.5)
SELECT ROUND(2.675, 2), ROUND(1.005, 2), ROUND(5.55, 1), ROUND(NULL), ROUND(10)
SELECT FLOOR(-1.5), FLOOR(1.5), CEIL(1.2), CEILING(-1.2), ABS(-3), ABS(-3.5), ABS(NULL), SIGN(-5), SIGN(0), SIGN(2.5)
SELECT POW(2, 10), POWER(2, 0.5), SQRT(16), SQRT(2), SQRT(-1), TRUNCATE(1.999, 1), TRUNCATE(-1.999, 1), TRUNCATE(1234, -2)
SELECT GREATEST(1, 3, 2), LEAST(1, 3, 2), GREATEST(1, NULL), LEAST('a', 'b'), GREATEST('10', '9'), GREATEST(10, '9')
SELECT EXP(0), LN(1), LOG(100), LOG10(100), LOG2(8), LOG(2, 8), PI(), DEGREES(PI()), RADIANS(180)
SELECT SIN(0), COS(0), TAN(0), ATAN(1), ASIN(1), ACOS(1)
SELECT CONV(255, 10, 16), BIN(5), OCT(8), HEX(255), HEX('abc'), UNHEX('616263')
SELECT 5 & 3, 5 | 3, 5 ^ 3, ~5, 1 << 3, 16 >> 2
# comparison and logic
SELECT 1 = 1, 1 <> 2, 1 != 1, 1 < 2, 2 <= 2, NULL = NULL, NULL <=> NULL, 1 <=> NULL, NULL IS NULL, 1 IS NOT NULL
SELECT 'a' = 'A', 'a' < 'B', 'a' = 'a ', 'abc' LIKE 'A%', 'abc' LIKE 'a_c', 'abc' LIKE 'ABC', 'a%b' LIKE 'a\%b', 'ab' LIKE '%'
SELECT 'é' = 'e', 'résumé' = 'resume', 'ä' = 'a', 'ß' = 'ss'
SELECT '10' < '9', 10 < 9, '10' < 9, 'a' = 0, '1a' = 1, '1' = 1.0, '1.0' = 1, '' = 0, 'abc' = 0, NULL < 1
SELECT 1 IN (1, 2), 3 IN (1, 2), 1 NOT IN (2, NULL), 1 IN (2, NULL), NULL IN (1), 1 IN (1, NULL), 'a' IN ('A', 'b')
SELECT 1 BETWEEN 0 AND 2, 5 BETWEEN 6 AND 1, NULL BETWEEN 1 AND 2, 'b' BETWEEN 'a' AND 'c', 2 NOT BETWEEN 1 AND 3
SELECT TRUE AND FALSE, TRUE OR NULL, FALSE AND NULL, NOT NULL, NOT 1, NOT 0, 1 AND 2, 0 OR 3, 1 XOR 1, NULL XOR 1
SELECT 1 = 1 AND 2 = 2, 5 > 3 OR 1 / 0, IF(1 > 2, 'y', 'n'), IF(NULL, 'y', 'n'), IFNULL(NULL, 5), IFNULL(1, 5), NULLIF(1, 1), NULLIF(1, 2)
SELECT COALESCE(NULL, NULL, 3), COALESCE(NULL, NULL), CASE WHEN 1 > 2 THEN 'a' ELSE 'b' END, CASE 2 WHEN 1 THEN 'x' WHEN 2 THEN 'y' END, CASE WHEN NULL THEN 1 ELSE 2 END
# strings
SELECT CONCAT('a', 'b', NULL), CONCAT('a', 1, 2.5), CONCAT_WS(',', 'a', NULL, 'b'), CONCAT_WS(NULL, 'a'), CONCAT()
SELECT UPPER('aBc'), LOWER('aBc'), UCASE('x'), LCASE('X'), LENGTH('héllo'), CHAR_LENGTH('héllo'), LENGTH(''), LENGTH(NULL), LENGTH(123)
SELECT SUBSTRING('hello', 2, 3), SUBSTRING('hello', -3), SUBSTRING('hello', 0), SUBSTRING('hello', 2), SUBSTRING('hello', 10), SUBSTRING('hello', 2, 0), SUBSTRING('hello', -3, 2), SUBSTR('hello', 2, 100)
SELECT SUBSTRING('hello' FROM 2 FOR 3), MID('hello', 2, 3), LEFT('hello', 2), RIGHT('hello', 2), LEFT('hello', 0), LEFT('hello', 10), LEFT(NULL, 1), RIGHT('hello', -1)
SELECT TRIM('  a  '), LTRIM('  a  '), RTRIM('  a  '), TRIM(BOTH 'x' FROM 'xxaxx'), TRIM(LEADING 'x' FROM 'xxaxx'), TRIM(TRAILING 'x' FROM 'xxaxx')
SELECT REPLACE('abcabc', 'b', 'X'), REPLACE('abc', '', 'X'), REPLACE(NULL, 'a', 'b'), REVERSE('abc'), REPEAT('ab', 3), REPEAT('ab', 0), REPEAT('ab', -1), SPACE(3)
SELECT INSTR('hello', 'l'), LOCATE('l', 'hello'), LOCATE('l', 'hello', 4), POSITION('l' IN 'hello'), INSTR('hello', 'z'), INSTR('Hello', 'h'), INSTR('hello', '')
SELECT LPAD('5', 3, '0'), RPAD('5', 3, '0'), LPAD('hello', 3, '0'), LPAD('5', 0, '0'), LPAD('5', 5, ''), LPAD('abc', 6, 'xy')
SELECT ASCII('A'), ASCII(''), ASCII('abc'), ORD('a'), CHAR(65, 66), CHAR(72, 101, 108, 108, 111), STRCMP('a', 'b'), STRCMP('b', 'a'), STRCMP('a', 'a'), STRCMP('a', 'A')
SELECT FORMAT(1234567.891, 2), FORMAT(0.5, 0), FORMAT(1234, 0), FORMAT(-1234.567, 1), FORMAT(NULL, 2)
SELECT FIELD('b', 'a', 'b', 'c'), FIND_IN_SET('b', 'a,b,c'), ELT(2, 'a', 'b', 'c'), INSERT('Quadratic', 3, 4, 'What'), LEFT(UUID(), 0)
SELECT BIT_LENGTH('abc'), OCTET_LENGTH('é'), SOUNDEX('Hello'), LOWER(NULL), UPPER(''), CONCAT('', ''), 'a' || 'b'
SELECT SUBSTRING_INDEX('a.b.c', '.', 2), SUBSTRING_INDEX('a.b.c', '.', -1), SUBSTRING_INDEX('a.b.c', '.', 0), SUBSTRING_INDEX('abc', '.', 1)
# casts and conversions
SELECT CAST('12abc' AS SIGNED), CAST('abc' AS SIGNED), CAST(3.7 AS SIGNED), CAST(-3.7 AS SIGNED), CAST('3.7' AS SIGNED), CAST('3.7' AS DECIMAL(5,1)), CAST(5 AS CHAR), CAST(NULL AS SIGNED)
SELECT CAST('2024-01-15' AS DATE), CAST('2024-01-15 10:20:30' AS DATE), CAST(20240115 AS DATE), CAST('2024-13-45' AS DATE), CAST(5 AS UNSIGNED), CAST(-5 AS UNSIGNED)
SELECT CAST(1.5 AS DECIMAL(3,0)), CAST(2.5 AS DECIMAL(3,0)), CAST('1e3' AS SIGNED), CAST(' 12 ' AS SIGNED), CAST(1 AS DOUBLE), CONVERT('12', SIGNED), CONVERT(12, CHAR)
# dates
SELECT DATE('2024-01-15 10:20:30'), YEAR('2024-03-05'), MONTH('2024-03-05'), DAY('2024-03-05'), DAYOFMONTH('2024-03-05'), DAYOFWEEK('2024-03-05'), DAYOFYEAR('2024-03-05'), WEEKDAY('2024-03-05')
SELECT QUARTER('2024-03-05'), WEEK('2024-03-05'), WEEKOFYEAR('2024-03-05'), MONTHNAME('2024-03-05'), DAYNAME('2024-03-05'), LAST_DAY('2024-02-10'), LAST_DAY('2023-02-10')
SELECT DATE_ADD('2024-01-31', INTERVAL 1 MONTH), DATE_SUB('2024-03-31', INTERVAL 1 MONTH), DATE_ADD('2024-02-29', INTERVAL 1 YEAR), DATE_ADD('2024-01-01', INTERVAL 36 HOUR), DATE_ADD('2024-01-01', INTERVAL -1 DAY)
SELECT DATEDIFF('2024-03-05', '2024-01-01'), DATEDIFF('2024-01-01', '2024-03-05'), TIMESTAMPDIFF(DAY, '2024-01-01', '2024-03-05'), TIMESTAMPDIFF(MONTH, '2024-01-31', '2024-02-29'), TIMESTAMPDIFF(YEAR, '2020-02-29', '2024-02-28')
SELECT DATE_FORMAT('2024-03-05 14:07:09', '%Y/%m/%d %H:%i:%s'), DATE_FORMAT('2024-03-05', '%W %M %e %y %b %a %j %U'), DATE_FORMAT('2024-03-05 14:07:09', '%h:%i %p'), DATE_FORMAT('2024-03-05', '%%')
SELECT STR_TO_DATE('05/03/2024', '%d/%m/%Y'), STR_TO_DATE('2024-3-5', '%Y-%m-%d'), STR_TO_DATE('abc', '%Y'), ADDDATE('2024-01-01', 10), SUBDATE('2024-01-01', 1), ADDDATE('2024-01-01', INTERVAL 1 MONTH)
SELECT HOUR('10:20:30'), MINUTE('10:20:30'), SECOND('10:20:30'), TIME('2024-01-01 10:20:30'), TIME_TO_SEC('01:00:00'), SEC_TO_TIME(3661), MAKEDATE(2024, 60), FROM_DAYS(739000), TO_DAYS('2024-01-01')
SELECT '2024-01-31' + INTERVAL 1 DAY, DATE('2024-02-30'), DATE('abc'), YEAR(NULL), '2024-03-05' > '2024-03-04', '2024-03-05' = DATE('2024-03-05'), DATE('2024-03-05') + 0
SELECT EXTRACT(YEAR FROM '2024-03-05'), EXTRACT(MONTH FROM '2024-03-05'), EXTRACT(DAY FROM '2024-03-05'), EXTRACT(HOUR FROM '2024-03-05 10:20:30'), EXTRACT(YEAR_MONTH FROM '2024-03-05')
SELECT UNIX_TIMESTAMP('2024-01-01 00:00:00') > 0, FROM_UNIXTIME(0) IS NOT NULL, DATE_FORMAT(FROM_UNIXTIME(86400), '%Y') >= '1970'
# json and misc
SELECT JSON_EXTRACT('{"a": 1, "b": [1,2]}', '$.a'), JSON_EXTRACT('{"a": 1, "b": [1,2]}', '$.b[1]'), JSON_UNQUOTE(JSON_EXTRACT('{"a": "x"}', '$.a')), JSON_LENGTH('[1,2,3]'), JSON_TYPE('[1]'), JSON_VALID('{'), JSON_VALID('{}')
SELECT JSON_OBJECT('a', 1, 'b', 'x'), JSON_ARRAY(1, 'a', NULL), JSON_CONTAINS('[1,2]', '1'), JSON_KEYS('{"a":1,"b":2}'), '{"a": 5}' -> '$.a', JSON_SET('{"a":1}', '$.b', 2)
SELECT MD5('abc'), SHA1('abc'), SHA2('abc', 256), LENGTH(UUID()), CRC32('abc'), TO_BASE64('abc'), FROM_BASE64('YWJj')
SELECT 1 + 1 AS two, 'x' AS s, NULL AS n, 1.50 AS d, 1e0 AS e
SELECT 0.1 + 0.2 = 0.3, 0.1 + 0.2, 1.0 = 1, 1.10, 1.1 + 1.10, 3.0 * 2, 3 * 2.0
SELECT 100000000000 * 100000000000, 123456789 * 987654321, 2 * 4611686018427387904, 18446744073709551615, 18446744073709551615 + 1, 9223372036854775808
SELECT 1.23456789012345678901234567890 + 1, 123456789012345678901234567890 + 1, 0.000000000001 * 0.000000000001
SELECT 7 / 7, 6 / 4, 4 / 6, 1 / 8, 22 / 7, 1 / 3 * 3, 10 / 3 * 3, 2 / 3 + 1 / 3
